package com.meridian.keystone.model; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity public class WorkOrder { @Id @GeneratedValue public Long id; public String title; @Column(length=2000) public String description; @Enumerated(EnumType.STRING) public WorkOrderStatus status=WorkOrderStatus.OPEN; public String assignedTo; public LocalDateTime createdAt=LocalDateTime.now(); }
